    await act(async () => {
      await vi.advanceTimersByTimeAsync(600);
    });
    await act(async () => {});

    const pops = document.querySelectorAll('.tc-pop');
    expect(pops).toHaveLength(1);
    expect(pops[0]?.querySelector('.tc-pop-title-text')?.textContent).toBe('The Matrix');
  });
});

